	width := 0
	for _, info := range commands {
		if w := utf8.RuneCountInString(info.Invocation); w > width {
			width = w
		}
	}

	var out strings.Builder
	for _, info := range commands {
		out.WriteString("  ")
		out.WriteString(padRight(info.Invocation, width))
		out.WriteByte(' ')
		out.WriteString(info.Summary)
		out.WriteByte('\n')
	}
	return out.String()
}

